css:
.anim-stage-motion-anim-box-1-1 .anim-box {
  animation: motion-anim-box-1-1-anim 0.6s linear infinite;
}

@keyframes motion-anim-box-1-1-anim {
  0% {
    transform:rotate(0)
  }100% {
    transform:rotate(360deg)
  }
}

.anim-stage-motion-anim-circle-2-2 .anim-circle {
